  static _Parsed? _parse(String input) {
    String s = input
        .trim()
        .replaceAll('−', '-')
        .replaceAll('²', '^2')
        .replaceAll(' ', '')
        .replaceAll('>=', '≠¥')
        .replaceAll('<=', '≠¤');

    if (!s.contains('|')) return null;

    final op = _extractOp(s);
    if (op == null) return null;

    final idx = s.indexOf(op);
    if (idx == -1) return null;

    final left = s.substring(0, idx);
    final right = s.substring(idx + op.length);

    bool absOnLeft;
    String absSide, constStr;
    if (left.contains('|')) {
      absSide = left; constStr = right; absOnLeft = true;
    } else if (right.contains('|')) {
      absSide = right; constStr = left; absOnLeft = false;
    } else {
      return null;
    }

    final inner = absSide.replaceAll('|', '');
    final k = double.tryParse(constStr);
    if (k == null) return null;

    final parsed = _parseLinear(inner);
    if (parsed == null) return null;

    return _Parsed(op: op, a: parsed['x']!, b: parsed['c']!, k: k, absOnLeft: absOnLeft);
  }

  static String? _extractOp(String s) {
    if (s.contains('≠¥')) return '≠¥';
    if (s.contains('≠¤')) return '≠¤';
    if (s.contains('>')) return '>';
    if (s.contains('<')) return '<';
    return null;
  }

  static Map<String, double>? _parseLinear(String expr) {
    expr = expr.trim().replaceAll(' ', '');
    if (expr.isEmpty) return null;
    double xCoef = 0, constant = 0;
    final tokens = <String>[];
    String cur = '';
    for (int i = 0; i < expr.length; i++) {
      final ch = expr[i];
      if ((ch == '+' || ch == '-') && i > 0) {
        if (cur.isNotEmpty) tokens.add(cur);
        cur = ch;
      } else { cur += ch; }
    }
    if (cur.isNotEmpty) tokens.add(cur);
    for (final tok in tokens) {
      if (tok.contains('x')) {
        final cs = tok.split('x')[0];
        if (cs.isEmpty || cs == '+') xCoef += 1;
        else if (cs == '-') xCoef -= 1;
        else xCoef += double.tryParse(cs) ?? 0;
      } else {
        constant += double.tryParse(tok) ?? 0;
      }
    }
    return {'x': xCoef, 'c': constant};
  }

  static String _coefLatex(double a) {
    if (a == 1) return '';
    if (a == -1) return '-';
    return _fmtLatex(a);
  }


  static String _fmt(double n) {
    if (n == 0) return '0';
    if (!n.isFinite) return n.isNaN ? 'NaN' : (n.isNegative ? '-∞' : '∞');
    if (n == n.roundToDouble()) return n.toInt().toString();
    for (int d = 2; d <= 20; d++) {
      final num = (n * d).round();
      if ((num / d - n).abs() < 1e-9) {
        int g = _gcd(num.abs(), d);
        final sn = num ~/ g;
        final sd = d ~/ g;
        if (sd == 1) return sn.toString();
        return '$sn/$sd';
      }
    }
    return n.toStringAsFixed(4);
  }

  static int _gcd(int a, int b) => b == 0 ? a : _gcd(b, a % b);

