    if (!n.isFinite) return n.isNaN ? 'NaN' : (n.isNegative ? r'-\infty' : r'\infty');
    if (n == n.roundToDouble()) return n.toInt().toString();
    for (int d = 2; d <= 20; d++) {
      final num = (n * d).round();
      if ((num / d - n).abs() < 1e-9) {
        int g = _gcd(num.abs(), d);
        final sn = num ~/ g;
        final sd = d ~/ g;
        if (sd == 1) return sn.toString();
        if (sn < 0) return r'-\frac{' + (-sn).toString() + '}{' + sd.toString() + '}';
        return r'\frac{' + sn.toString() + '}{' + sd.toString() + '}';
      }
    }
    return n.toStringAsFixed(4);
  }

  static String _toLatexInterval(String s) {
    return s
        .replaceAll('\u221e', r'\infty')
        .replaceAll('\u2205', r'\emptyset')
        .replaceAll('\u222a', r'\cup');
  }

  static String _texOp(String op) {
    switch (op) {
      case '≠¥': return '\\geq';
      case '≠¤': return '\\leq';
      case '>': return '>';
      case '<': return '<';
      default: return op;
    }
  }

  static String _flipOp(String op) {
    switch (op) {
      case '>': return '<';
      case '<': return '>';
      case '≠¥': return '≠¤';
      case '≠¤': return '≠¥';
      default: return op;
    }
  }


  /// Replace |...| with \lvert...\rvert for proper LaTeX absolute value rendering
  static String _absToLatex(String s) {
    final buf = StringBuffer();
    bool inAbs = false;
    for (int i = 0; i < s.length; i++) {
      if (s[i] == '|') {
        if (!inAbs) {
          buf.write(r'\lvert ');
          inAbs = true;
        } else {
          buf.write(r' \rvert');
          inAbs = false;
        }
      } else {
        buf.write(s[i]);
      }
    }
    return buf.toString();
  }
}

class _Parsed {
  final String op;
  final double a, b, k;
  final bool absOnLeft;
  const _Parsed({required this.op, required this.a, required this.b, required this.k, required this.absOnLeft});
}
